    var placements: [WindowID: CGRect] = [:]
    placements.reserveCapacity(windowIDs.count)
    var remaining = rect
    var axis = horizontal
    for (index, id) in windowIDs.enumerated() {
        let tailCount = windowIDs.count - index - 1
        if tailCount == 0 {
            placements[id] = remaining.integral
        } else {
            let parts = split(remaining, horizontally: axis, gap: gap, firstCount: 1, secondCount: tailCount)
